insert into ebd.biblia_versiculos (traducao_id, livro_numero, livro, livro_abreviado, capitulo, versiculo, texto)
values
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 102, 'Não me desviei de teus juízos, porque tu me ensinaste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 103, 'Como são doces tuas palavras ao meu paladar! Mais que o mel em minha boca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 104, 'Obtenho conhecimento por meio de teus preceitos; por isso odeio todo caminho de mentira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 105, '[Nun] :Tua palavra é lâmpada para meus pés e luz para meu caminho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 106, 'Eu jurei, e [assim] cumprirei, de guardar os juízos de tua justiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 107, 'Eu estou muito aflito, SENHOR; vivifica-me conforme a tua palavra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 108, 'Agrada-te das ofertas voluntárias de minha boca, SENHOR; e ensina-me teus juízos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 109, 'Continuamente arrisco minha alma, porém não me esqueço de tua lei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 110, 'Os perversos me armaram um laço de armadilha, mas não me desviei de teus mandamentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 111, 'Tomei teus testemunhos por herança para sempre, pois eles são a alegria de meu coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 112, 'Inclinei meu coração para praticar os teus testemunhos para todo o sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 113, '[Sâmeque] :Odeio os inconstantes, mas amo a tua lei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 114, 'Tu és meu refúgio e meu escudo; eu espero em tua palavra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 115, 'Afastai-vos de mim, malfeitores, para que eu guarde os mandamentos de meu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 116, 'Sustenta-me conforme a tua promessa, para que eu viva; e não me faças ser humilhado em minha esperança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 117, 'Segura-me, e estarei protegido; então continuamente pensarei em teus estatutos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 118, 'Tu atropelas a todos que se desviam de teus estatutos; pois o engano deles é mentira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 119, 'Tu tiras a todos os perversos da terra como [se fossem] lixo; por isso eu amo teus testemunhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 120, 'Meu corpo se arrepia de medo de ti; e temo os teus juízos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 121, '[Áin] :Eu fiz juízo e justiça; não me abandones com os meus opressores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 122, 'Sê tu a garantia do bem de teu servo; não me deixes ser oprimido pelos arrogantes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 123, 'Meus olhos desfaleceram [de esperar] por tua salvação, e pela palavra de tua justiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 124, 'Age para com teu servo segundo tua bondade, e ensina-me teus estatutos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 125, 'Eu sou teu servo. Dá-me entendimento; então conhecerei teus testemunhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 126, 'É tempo do SENHOR agir, porque estão violando tua lei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 127, 'Por isso eu amo teus mandamentos mais que o ouro, o mais fino ouro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 128, 'Por isso considero corretos todos os [teus] mandamentos quanto a tudo, e odeio todo caminho de falsidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 129, '[Pê] :Maravilhosos são teus testemunhos, por isso minha alma os guarda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 130, 'A entrada de tuas palavras dá luz, dando entendimento aos simples.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 131, 'Abri minha boca, e respirei; porque desejei teus mandamentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 132, 'Olha-me, e tem piedade de mim; conforme [teu] costume para com os que amam o teu nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 133, 'Firma meus passos em tua palavra, e que nenhuma perversidade me domine.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 134, 'Resgata-me da opressão dos homens; então guardarei teus mandamentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 135, 'Brilha teu rosto sobre teu servo, e ensina-me teus estatutos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 136, 'Ribeiros d''água descem de meus olhos, porque eles não guardam tua lei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 137, '[Tsadê] :Tu és justo, SENHOR; e corretos são teus juízos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 138, 'Tu ensinaste teus testemunhos justos e muito fiéis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 139, 'Meu zelo me consumiu, porque meus adversários se esqueceram de tuas palavras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 140, 'Refinada é a tua palavra, e teu servo a ama.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 141, 'Eu sou pequeno e desprezado; [porém] não me esqueço de teus mandamentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 142, 'Tua justiça é justa para sempre, e tua lei é verdade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 143, 'Aperto e angústia me encontraram; [ainda assim] teus mandamentos são meus prazeres.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 144, 'A justiça de teus testemunhos [dura] para sempre; dá-me entendimento, e então viverei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 145, '[Cofe] :Clamei com todo o [meu] coração; responde-me, SENHOR; guardarei teus estatutos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 146, 'Clamei a ti; salva-me, e então guardarei os teus testemunhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 147, 'Eu me antecedi ao amanhecer, e gritei; [e] mantive esperança em tua palavra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 148, 'Meus olhos antecederam as vigílias da noite, para meditar em tua palavra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 149, 'Ouve minha voz, segundo tua bondade, SENHOR; vivifica-me conforme teu juízo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 150, 'Aproximam-se [de mim] os que praticam maldade; eles estão longe de tua lei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 151, '[Porém] tu, SENHOR, estás perto [de mim] ; e todos os teus mandamentos são verdade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 152, 'Desde antigamente eu soube de teus testemunhos, que tu os fundaste para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 153, '[Rexe] :Olha a minha aflição, e livra-me [dela] ; pois não me esqueci de tua lei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 154, 'Defende minha causa, e resgata-me; vivifica-me conforme tua palavra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 155, 'A salvação está longe dos perversos, porque eles não buscam teus estatutos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 156, 'Muitas são tuas misericórdias, SENHOR; vivifica-me conforme teus juízos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 157, 'Muitos são meus perseguidores e meus adversários; [porém] eu não me desvio de teus testemunhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 158, 'Eu vi aos enganadores e os detestei, porque eles não guardam tua palavra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 159, 'Vê, SENHOR, que eu amo teus mandamentos; vivifica-me conforme a tua bondade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 160, 'O princípio de tua palavra é fiel, e o juízo de tua justiça [dura] para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 161, '[Xin] :Príncipes me perseguiram sem causa, mas meu coração temeu a tua palavra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 162, 'Eu me alegro em tua palavra, tal como alguém que encontra um grande tesouro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 163, 'Odeio e abomino a falsidade; [mas] amo a tua lei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 164, 'Louvo a ti sete vezes ao dia, por causa dos juízos de tua justiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 165, 'Muita paz têm aqueles que amam a tua lei; e para eles não há tropeço.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 166, 'Espero por tua salvação, SENHOR; e pratico teus mandamentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 167, 'Minha alma guarda teus testemunhos, e eu os amo muito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 168, 'Eu guardo teus preceitos e teus testemunhos, porque todos os meus caminhos estão diante de ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 169, '[Tau] :Chegue meu clamor perante teu rosto, SENHOR; dá-me entendimento conforme tua palavra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 170, 'Venha minha súplica diante de ti; livra-me conforme tua promessa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 171, 'Meus lábios falarão muitos louvores, pois tu me ensinas teus estatutos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 172, 'Minha língua falará de tua palavra, porque todos os teus mandamentos são justiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 173, 'Que tua mão me socorra, porque escolhi [seguir] teus preceitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 174, 'Desejo tua salvação, SENHOR; e tua lei é o meu prazer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 175, 'Que minha alma viva e louve a ti; e que teus juízos me socorram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 119, 176, 'Tenho andado sem rumo, como uma ovelha perdida; busca a teu servo, pois eu não me esqueci de teus mandamentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 120, 1, 'Cântico dos degraus: Em minha angústia clamei ao SENHOR, e ele me respondeu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 120, 2, 'Ó SENHOR, livra minha alma dos lábios mentirosos, da língua enganadora.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 120, 3, 'O que ele te dará, e o que ele fará contigo, ó língua enganadora?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 120, 4, 'Flechas afiadas de um guerreiro, com brasas de zimbro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 120, 5, 'Ai de mim, que peregrino em Meseque, [e] habito nas tendas de Quedar!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 120, 6, 'Minha alma morou [tempo] demais com os que odeiam a paz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 120, 7, 'Eu sou da paz; mas quando falo, eles [entram] em guerra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 121, 1, 'Cântico dos degraus: Levanto meus olhos aos montes. De onde virá meu socorro?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 121, 2, 'Meu socorro [vem] do SENHOR, que fez os céus e a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 121, 3, 'Ele não deixará o teu pé se abalar, nem cochilará o teu guardião.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 121, 4, 'Eis que não cochilará nem dormirá o Guardião de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 121, 5, 'O SENHOR é o teu guardião; o SENHOR é a sombra à tua direita.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 121, 6, 'O sol não te ferirá durante o dia, nem a lua durante a noite.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 121, 7, 'O SENHOR te guardará de todo mal; ele guardará a tua alma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 121, 8, 'O SENHOR guardará tua saída e tua entrada, desde agora e para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 122, 1, 'Cântico dos degraus, de Davi: Alegro-me com os que me dizem: Vamos à casa do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 122, 2, 'Nossos pés estão [adentro] de tuas portas, ó Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 122, 3, 'Jerusalém está edificada como uma cidade bem unida;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 122, 4, 'Para onde as tribos sobem, as tribos do SENHOR, como testemunho de Israel, para agradecerem ao nome do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 122, 5, 'Porque ali estão as cadeiras do julgamento; as cadeiras da casa de Davi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 122, 6, 'Orai pela paz de Jerusalém; prosperem os que te amam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 122, 7, 'Paz haja em teus muros, e prosperidade em tuas fortalezas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 122, 8, 'Por meus irmãos e amigos, assim falarei: Paz haja em ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 122, 9, 'Pela Casa do SENHOR nosso Deus, buscarei o bem para ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 123, 1, 'Cântico dos degraus: Levanto meus olhos a ti, que moras nos céus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 123, 2, 'Eis que, assim como os olhos dos servos [olham] para a mão de seus senhores, e os olhos da serva para a mão de sua senhora, assim também nossos olhos [olharão] para o SENHOR nosso Deus, até que ele tenha piedade de nós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 123, 3, 'Tem piedade de nós, SENHOR! Tem piedade de nós; pois temos sido humilhados em excesso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 123, 4, 'Nossa alma está cheia da zombaria dos insolentes, e da humilhação dos arrogantes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 124, 1, 'Cântico dos degraus, de Davi: Diga, Israel: O que [seria de nós] se o SENHOR não estivesse conosco?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 124, 2, 'Se o SENHOR não estivesse conosco, quando os homens se levantaram contra nós,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 124, 3, 'Eles teriam nos devorado vivos, quando o furor deles se acendeu contra nós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 124, 4, 'As águas teriam nos coberto, [e] a corrente de águas teria passado por sobre nossas almas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 124, 5, 'Águas violentas teriam passado por sobre nossas almas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 124, 6, 'Bendito seja o SENHOR, que não nos entregou como presa aos dentes deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 124, 7, 'Nossa alma escapou como um pássaro da armadilha dos caçadores; a cadeia se quebrou, e nós escapamos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 124, 8, 'Nosso socorro está no nome do SENHOR, que fez o céu e a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 125, 1, 'Os que confiam no SENHOR são como o monte de Sião, que não se abala, [e] permanece para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 125, 2, 'Assim como montanhas estão ao redor de Jerusalém, assim também o SENHOR está ao redor de seu povo, desde agora para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 125, 3, 'Porque o cetro da maldade não repousará sobre a sorte dos justos, para que os justos não estendam suas mãos à perversidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 125, 4, 'SENHOR, trata bem aos bons, e aos corretos em seus corações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 125, 5, 'Mas aos que se dirigem a seus caminhos tortuosos, o SENHOR os mandará embora junto com os que praticam perversidade. Paz [seja] sobre Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 126, 1, 'Cântico dos degraus: Quando o SENHOR restaurou Sião de seu infortúnio, estivemos como os que sonham.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 126, 2, 'Então nossa boca se encheu de riso, e nossa língua de alegria; então diziam entre as nações: O SENHOR fez grandes coisas para estes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 126, 3, 'Grandes coisas o SENHOR fez para nós; [por isso] estamos alegres.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 126, 4, 'Restaura-nos, ó SENHOR, como as correntes de águas no sul.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 126, 5, 'Os que semeiam em lágrimas colherão com alegria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 126, 6, 'Aquele que sai chorando com semente para semear voltará com alegria, trazendo sua colheita.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 127, 1, 'Cântico dos degraus, de Salomão: Se o SENHOR não estiver edificando a casa, em vão trabalham nela seus construtores; se o SENHOR não estiver guardando a cidade, em vão o guarda vigia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 127, 2, 'Inutilmente levantais de madrugada [e] descansais tarde, para comerdes o pão de dores; [porque] assim ele dá sono a quem ele ama.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 127, 3, 'Eis que os filhos são um presente do SENHOR; o fruto do ventre é uma recompensa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 127, 4, 'Como flechas na mão do guerreiro, assim são os filhos da juventude.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 127, 5, 'Bem-aventurado é o homem que enche deles seu porta-flechas; eles não serão envergonhados, quando falarem com os inimigos à porta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 128, 1, 'Cântico dos degraus: Bem-aventurado todo aquele que teme ao SENHOR, [e] anda em seus caminhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 128, 2, 'Porque comerás do trabalho de tuas mãos; tu serás bem-aventurado, e bem lhe [sucederá] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 128, 3, 'Tua mulher será como a videira frutífera, ao lado de tua casa; [e] teus filhos como plantas de oliveira ao redor de tua mesa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 128, 4, 'Eis que assim é bendito o homem que teme ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 128, 5, 'O SENHOR te abençoará desde Sião, e tu verás o bem de Jerusalém todos os dias de tua vida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 128, 6, 'E verás os filhos de teus filhos, [e] a paz sobre Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 129, 1, 'Cântico dos degraus: Diga Israel: Desde minha juventude muitas vezes me afligiram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 129, 2, 'Desde minha juventude, muitas vezes me afligiram, porém não prevaleceram contra mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 129, 3, 'Lavradores lavraram sobre minhas costas, fizeram compridos os seus sulcos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 129, 4, 'O SENHOR é justo; ele cortou as cordas dos perversos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 129, 5, 'Sejam envergonhados, e voltem para trás todos os que odeiam a Sião.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 129, 6, 'Sejam como a erva dos telhados, que se seca antes que cresça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 129, 7, 'Com que o ceifeiro não enche sua mão, nem o braço daquele que amarra os molhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 129, 8, 'Nem também os que passam, dizem: A bênção do SENHOR seja sobre vós; nós vos bendizemos no nome do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 130, 1, 'Cântico dos degraus: Das profundezas clamo a ti, SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 130, 2, 'Ouve, Senhor, a minha voz; sejam teus ouvidos atentos à voz de minhas súplicas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 130, 3, 'Se tu, SENHOR, considerares todas as perversidades, quem resistirá, Senhor?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 130, 4, 'Mas contigo está o perdão, para que tu sejas temido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 130, 5, 'Mantenho esperança no SENHOR, a minha alma espera; e persisto em sua palavra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 130, 6, 'Minha alma [espera ansiosamente] pelo Senhor, mais que os guardas [esperam] pela manhã, [mais] que os vigilantes pelo alvorecer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 130, 7, 'Espere, Israel, pelo SENHOR; porque com o SENHOR há bondade, e com ele muito resgate.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 130, 8, 'E ele resgatará Israel de todas as suas perversidades.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 131, 1, 'Cântico dos degraus, de Davi: SENHOR, meu coração não se exaltou, nem meus olhos se levantaram; nem andei em grandezas, nem em coisas maravilhosas para mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 131, 2, 'Ao invés disso, eu me sosseguei e calei minha alma, tal como uma criança com sua mãe; como um bebê está minha alma comigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 131, 3, 'Ó Israel, espere no SENHOR, desde agora para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 132, 1, 'Cântico dos degraus: Lembra-te, SENHOR, de Davi, [e] de todas as aflições dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 132, 2, 'Ele, que jurou ao SENHOR, [e] fez um voto ao Poderoso de Jacó,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 132, 3, '[dizendo] : Não entrarei na tenda de minha casa, nem subirei no leito de minha cama;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 132, 4, 'Não darei sono aos meus olhos, [nem] cochilo às minhas pálpebras;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 132, 5, 'Enquanto eu não achar um lugar para o SENHOR, moradas para o Poderoso de Jacó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 132, 6, 'Eis que ouvimos dela em Efrata, e [a] achamos nos campos de Jaar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 132, 7, 'Entraremos em suas moradas, [e] nos prostraremos perante o escabelo de seus pés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 132, 8, 'Levanta-te, SENHOR, a teu repouso; tu e a arca de teu poder.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 132, 9, 'Que teus sacerdotes se vistam de justiça, e teus santos gritem de alegria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 132, 10, 'Por causa de Davi teu servo, não rejeites o rosto de teu ungido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 132, 11, 'O SENHOR jurou a Davi [com] fidelidade; dela não se desviará. [Ele disse] : Do fruto do teu ventre porei sobre o teu trono.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 132, 12, 'Se teus filhos guardarem meu pacto e meus testemunhos que eu lhes ensinar, também seus filhos se sentarão sobre teu trono para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 132, 13, 'Porque o SENHOR escolheu a Sião, desejou-a para sua habitação,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 132, 14, '[Dizendo] : Este é o meu repouso para sempre; aqui habitarei, pois assim desejei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 132, 15, 'Abençoarei seu sustento abundantemente, [e] fartarei seus necessitados de pão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 132, 16, 'E a seus sacerdotes vestirei de salvação; e seus santos gritarão de alegria abundantemente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 132, 17, 'Ali farei brotar o poder de Davi; e preparei uma lâmpada para o meu ungido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 132, 18, 'A seus inimigos vestirei de vergonha; mas sobre ele florescerá sua coroa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 133, 1, 'Cântico dos degraus, de Davi: Vede como é bom e agradável que irmãos convivam em união!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 133, 2, 'É como o óleo precioso sobre a cabeça, que desce pela barba, a barba de Arão; que desce pelas bordas de suas roupas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 133, 3, 'É como o orvalho de Hermom, que desce sobre os montes de Sião; porque ali o SENHOR ordenou a bênção [e] a vida para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 134, 1, 'Cântico dos degraus: Bendizei, pois, ao SENHOR, todos vós servos do SENHOR, que prestais serviço à casa do SENHOR durante as noites.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 134, 2, 'Levantai vossas mãos ao Santuário, e bendizei ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 134, 3, 'Que o SENHOR, o criador do céu e da terra, te abençoe desde Sião.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 135, 1, 'Aleluia! Louvai o nome do SENHOR; louvai [-o] vós, servos do SENHOR,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 135, 2, 'Que prestais serviço na Casa do SENHOR, nos pátios da Casa do nosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 135, 3, 'Louvai ao SENHOR, porque o SENHOR é bom; cantai louvores ao seu nome, porque é agradável;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 135, 4, 'Porque o SENHOR escolheu para si a Jacó, a Israel como propriedade sua;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 135, 5, 'Porque eu sei que o SENHOR é grande, e nosso Senhor está acima de todos os deuses.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 135, 6, 'O SENHOR faz tudo o que quer, nos céus, na terra, nos mares, e [em] todos os abismos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 135, 7, 'Ele faz as nuvens subirem desde os confins da terra, faz os relâmpagos com a chuva; ele produz os ventos de seus tesouros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 135, 8, 'Ele feriu os primogênitos do Egito, desde os homens até os animais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 135, 9, 'Ele enviou sinais e prodígios no meio de ti, Egito; contra Faraó, e contra todos os seus servos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 135, 10, 'Ele feriu muitas nações, e matou reis poderosos:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 135, 11, 'Seom, rei dos amorreus, e Ogue, rei de Basã; e todos os reinos de Canaã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 135, 12, 'E deu a terra deles como herança; como herança a Israel, seu povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 135, 13, 'Ó SENHOR, teu nome [dura] para sempre; [e] tua memória, SENHOR, de geração em geração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 135, 14, 'Porque o SENHOR julgará a seu povo; e terá compaixão de seus servos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 135, 15, 'Os ídolos das nações [são] prata e ouro; [são] obra de mãos humanas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 135, 16, 'Têm boca, mas não falam; têm olhos, mas não veem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 135, 17, 'Têm ouvidos, mas não ouvem; não têm respiração em sua boca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 135, 18, 'Tornem-se como eles os que os fazem, [e] todos os que confiam neles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 135, 19, 'Casa de Israel, bendizei ao SENHOR! Casa de Arão, bendizei ao SENHOR!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 135, 20, 'Casa de Levi, bendizei ao SENHOR! Vós que temeis ao SENHOR, bendizei ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 135, 21, 'Bendito seja o SENHOR desde Sião, ele que habita em Jerusalém. Aleluia!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 136, 1, 'Agradecei ao SENHOR, porque ele é bom, porque sua bondade [dura] para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 136, 2, 'Agradecei ao Deus dos deuses, porque sua bondade [dura] para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 136, 3, 'Agradecei ao SENHOR dos senhores; porque sua bondade [dura] para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 136, 4, 'Ao que faz grandes maravilhas sozinho por si mesmo; porque sua bondade [dura] para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 136, 5, 'Ao que fez os céus com entendimento; porque sua bondade [dura] para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 136, 6, 'Ao que estendeu a terra sobre as águas; porque sua bondade [dura] para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 136, 7, 'Ao que fez as grandes fontes de luz; porque sua bondade [dura] para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 136, 8, 'Ao sol, para governar o dia; porque sua bondade [dura] para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 136, 9, 'À lua e as estrelas, para governarem a noite; porque sua bondade [dura] para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 136, 10, 'Ao que feriu aos egípcios em seus primogênitos; porque sua bondade [dura] para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 136, 11, 'E tirou Israel do meio deles; porque sua bondade [dura] para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 136, 12, 'Com mão forte, e com braço estendido; porque sua bondade [dura] para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 136, 13, 'Ao que separou o mar Vermelho em [duas] partes; porque sua bondade [dura] para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 136, 14, 'E fez Israel passar por meio dele; porque sua bondade [dura] para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 136, 15, 'E derrubou a Faraó com seu exército no mar Vermelho; porque sua bondade [dura] para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 136, 16, 'Ao que guiou seu povo pelo deserto; porque sua bondade [dura] para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 136, 17, 'Ao que feriu grandes reis; porque sua bondade [dura] para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 136, 18, 'E matou reis poderosos; porque sua bondade [dura] para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 136, 19, 'Seom; rei amorreu; porque sua bondade [dura] para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 136, 20, 'E Ogue, rei de Basã; porque sua bondade [dura] para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 136, 21, 'E deu a terra deles como herança; porque sua bondade [dura] para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 136, 22, '[Como] herança a seu servo Israel; porque sua bondade [dura] para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 136, 23, 'O que em nossa humilhação se lembrou de nós; porque sua bondade [dura] para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 136, 24, 'E nos tirou livres de nossos adversários; porque sua bondade [dura] para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 136, 25, 'O que dá alimento a todo [ser vivo feito de] carne; porque sua bondade [dura] para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 136, 26, 'Agradecei ao Deus dos céus; porque sua bondade [dura] para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 137, 1, 'Junto aos rios da Babilônia nos sentamos e choramos, enquanto nos lembramos de Sião.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 137, 2, 'Sobre os salgueiros que há no meio dela penduramos nossas harpas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 137, 3, 'Porque ali os que tinham nos capturado nos pediam letras de canções, e os que nos destruíram, que [os] alegrássemos, [dizendo] : Cantai para nós [algumas] das canções de Sião.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 137, 4, 'Como cantaríamos canções do SENHOR em terra estrangeira?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 137, 5, 'Se eu me esquecer de ti, ó Jerusalém, que minha mão direita se esqueça [de sua habilidade] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 137, 6, 'Que minha língua grude no céu da boca se eu não me lembrar de ti, se eu não pôr Jerusalém acima de todas as minhas alegrias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 137, 7, 'Lembra-te, SENHOR, dos filhos de Edom no dia de Jerusalém, que diziam: Arruinai [-a] ,arruinai [-a] ,até ao seus fundamentos!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 137, 8, 'Ah filha de Babilônia, que serás destruída! Bem-aventurado a quem te retribuir o que fizeste conosco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 137, 9, 'Bem-aventurado aquele que tomar dos teus filhos, e [lançá-los] contra as pedras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 138, 1, 'Salmo de Davi: Louvarei a ti com todo o meu coração; na presença dos deuses cantarei louvores a ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 138, 2, 'Eu me prostrarei ao teu santo templo, e louvarei o teu nome por tua bondade e por tua verdade; porque engrandeceste tua palavra [e] teu nome acima de tudo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 138, 3, 'No dia [em que] clamei, tu me respondeste; [e] me fortaleceste [com] força em minha alma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 138, 4, 'Todos os reis da terra louvarão a ti, SENHOR, quando ouvirem as palavras de tua boca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 138, 5, 'E cantarão sobre os caminhos do SENHOR, pois grande [é] a glória do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 138, 6, 'Porque [mesmo] sendo SENHOR elevado, ele presta atenção ao humilde; porém ele reconhece o arrogante de longe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 138, 7, 'Enquanto ando no meio da angústia, tu me vivificas; tu estendes tua mão contra a ira de meus inimigos; e tua mão direita me salva.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 138, 8, 'O SENHOR fará por completo [o que ele tem] para mim; ó SENHOR, tua bondade [dura] para sempre; não abandones as obras de tuas mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 139, 1, 'Salmo de Davi, para o regente: SENHOR, tu me examinas e me conheces.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 139, 2, 'Tu sabes o meu sentar e o meu caminhar; de longe entendes meus pensamentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 139, 3, 'Tu cercas o meu andar e meu deitar; conheces desde antes os meus caminhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 139, 4, 'Mesmo não havendo [ainda] palavra [alguma] em minha língua, eis, SENHOR, que já sabes tudo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 139, 5, 'Tu me envolves por detrás e pela frente, e pões tua mão sobre mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 139, 6, '[Teu] conhecimento é maravilhoso demais para mim, tão alto que não posso [alcançá] -lo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 139, 7, 'Para onde eu escaparia de teu Espírito? E para onde fugiria de tua presença?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 139, 8, 'Se eu subisse até os céus, lá tu [estás] ; se eu fizer meu leito no Xeol, eis que tu [também ali estás] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 139, 9, 'Se eu tomasse as asas do amanhecer, e morasse nas extremidades do mar,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 139, 10, 'Até ali tua mão me guiaria, e tua mão direita me seguraria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 139, 11, 'Se eu dissesse: Certamente as trevas me encobrirão; e a luz ao redor de mim [será como] a noite.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 139, 12, 'Porém nem mesmo as trevas [me] esconderão de ti; ao invés disso, [pois] a noite é tão clara quanto o dia, [e aos teus olhos] as trevas são como a luz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 139, 13, 'Porque tu és dono do meu ser, e me cobriste no ventre da minha mãe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 139, 14, 'Eu te louvarei porque de um [jeito] assombroso e maravilhoso eu fui feito; maravilhosas [são] tuas obras; e minha alma sabe muito bem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 139, 15, 'Meus ossos não estavam escondidos de ti quando eu fui feito em oculto, e formado como tramas de tecido nas profundezas da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 139, 16, 'Teus olhos viram meu corpo [ainda] sem forma, e tudo estava escrito em teu livro; [até] os dias estavam determinados quando nenhum deles [ainda] havia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 139, 17, 'Como são preciosos para mim os teus pensamentos, Deus! Como é grande a quantidade deles!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 139, 18, 'Se eu os contasse, seriam muito mais [numerosos] que a areia; [quando] acordo, ainda estou contigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 139, 19, 'Ah, Deus, tomara que mates ao perverso! E vós, homens sanguinários, afastai-vos de mim;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 139, 20, 'Porque eles falam de ti com maldade, [e] teus inimigos [se] exaltam em vão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 139, 21, 'Por acaso, SENHOR, eu não odiaria aos que te odeiam? E não detestaria os que se levantam contra ti?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 139, 22, 'Eu os odeio com ódio completo; eu os considero como inimigos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 139, 23, 'Examina-me, Deus, e conhece meu coração; prova-me, e conhece meus pensamentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 139, 24, 'E vê se em mim [há algum] mau caminho; e guia-me pelo caminho eterno.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 140, 1, 'Salmo de Davi, para o regente: Livra-me do homem mau, SENHOR; guarda-me dos homens violentos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 140, 2, 'Que pensam maldades no coração; todo dia se reúnem para fazerem guerra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 140, 3, 'Eles afiam suas línguas como a cobra; veneno de serpentes [há] debaixo de seus lábios. (Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 140, 4, 'Guarda-me, SENHOR, das mãos do perverso; guarda-me do homens violentos, que pensam em empurrar os meus pés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 140, 5, 'Os arrogantes me armaram ciladas e cordas; estenderam uma rede de um lado do caminho; [e] puseram laços de armadilhas para mim. (Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 140, 6, 'Eu disse ao SENHOR: Tu [és] meu Deus; inclina teus ouvidos à voz de minhas súplicas, SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 140, 7, 'Ó Senhor DEUS, força de minha salvação, cobriste minha cabeça no dia da batalha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 140, 8, 'Não concedas ao perverso os desejos dele, SENHOR; não permitas suceder seu plano maligno, [pois senão] se exaltariam. (Selá)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 140, 9, 'Quanto à cabeça dos que me cercam, que a opressão de seus próprios lábios os cubra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 140, 10, 'Caiam sobre eles brasas vivas; faça-os cair no fogo [e] em covas profundas, [para que] não se levantem mais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 140, 11, 'O homem de língua maligna não se firmará na terra; o mal perseguirá o homem violento até o derrubar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 140, 12, 'Eu sei que o SENHOR cumprirá a causa do aflito, o direito dos necessitados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 140, 13, 'Certamente os justos agradecerão ao teu nome; os corretos habitarão perante teu rosto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 141, 1, 'Salmo de Davi: Ó SENHOR, eu clamo a ti; apressa-te a mim; ouve minha voz, quando eu clamar a ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 141, 2, 'Apresente-se minha oração [como] incenso diante de ti; [e] o levantar de minhas mãos [como] a oferta do anoitecer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 141, 3, 'Põe, SENHOR, uma guarda em minha boca; vigia a abertura dos meus lábios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 141, 4, 'Não inclines meu coração para as coisas más, para fazer o mal junto com homens que praticam maldade; e não coma eu das delícias deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 141, 5, 'Que o justo me faça o favor de me espancar e me repreender; [isto me será] azeite sobre a cabeça; minha cabeça não rejeitará, porque ainda orarei contra as maldades deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 141, 6, '[Quando] seus juízes forem lançados contra a rocha, então ouvirão minhas palavras, porque [são] agradáveis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 141, 7, 'Como quem lavra e fende a terra, assim nossos ossos são espalhados à entrada do Xeol.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 141, 8, 'Porém meus olhos [estão voltados] para ti, ó Senhor DEUS; em ti confio; não desampares minha alma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 141, 9, 'Guarda-me do perigo da armadilha que me prepararam; e dos laços da cilada dos que praticam maldade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 141, 10, 'Caiam os perversos cada um em suas próprias redes, e eu passe adiante [em segurança] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 142, 1, 'Instrução de Davi; oração quando ele estava na caverna: Com minha voz clamo ao SENHOR; com minha voz suplico ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 142, 2, 'Diante dele derramo meu pedido; diante dele contei minha angústia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 142, 3, 'Estando meu espírito angustiado em mim, tu conheceste meu percurso; no caminho em que eu andava esconderam um laço de armadilha para mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 142, 4, 'Eu olho à direita, e eis que não há quem me conheça; não há nenhum refúgio para mim; nem ninguém se importava com minha alma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 142, 5, 'Eu clamo a ti, SENHOR, dizendo: Tu és meu refúgio, [e] minha porção na terra dos viventes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 142, 6, 'Presta atenção aos meus gritos, porque estou muito oprimido; resgata-me daqueles que me perseguem, pois são mais fortes que eu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 142, 7, 'Tira minha alma da prisão, para que eu louve o teu nome; os justos me rodearão, porque tu me tratarás bem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 143, 1, 'Salmo de Davi: Ó SENHOR, ouve minha oração; inclina teus ouvidos às minhas súplicas; responde-me segundo tua fidelidade [e] tua justiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 143, 2, 'E não entres em juízo com teu servo; porque nenhum ser vivo será justo diante de ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 143, 3, 'Pois o inimigo persegue minha alma, atropela na terra a minha vida; [e] me obriga a viver na escuridão, como os que há muito [tempo] morreram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 143, 4, 'Por isso meu espírito se enche de angústia em mim, [e] meu coração está desesperado dentro de mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 143, 5, 'Lembro-me dos dias antigos, eu considero todos os teus feitos; medito nas obras de tuas mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 143, 6, 'Levanto minhas mãos a ti; minha alma [tem sede] de ti como a terra seca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 143, 7, 'Responde-me depressa, SENHOR; porque meu espírito está muito fraco; não escondas tua face de mim, pois eu seria semelhante aos que descem à cova.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 143, 8, 'De madrugada faze com que eu ouça tua bondade, porque em ti confio; faze-me saber o caminho que devo seguir, porque a ti levanto minha alma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 143, 9, 'Livra-me de meus inimigos, SENHOR; [pois] em ti eu me escondo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 143, 10, 'Ensina-me a fazer a tua vontade, pois tu és meu Deus; teu bom Espírito me guie por terra plana.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 143, 11, 'Vivifica-me por teu nome, SENHOR; por tua justiça tira minha alma da angústia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 143, 12, 'E por tua bondade extermina os meus inimigos; e destrói a todos os que afligem a minha alma; pois eu sou teu servo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 144, 1, 'Salmo de Davi: Bendito [seja] o SENHOR, rocha minha, que ensina minhas mãos para a batalha, [e] meus dedos para a guerra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 144, 2, '[Ele é] minha bondade e meu castelo; meu alto refúgio, e meu libertador; [ele é] meu escudo, em quem confio; [e] aquele que faz meu povo se submeter a mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 144, 3, 'Ó SENHOR, o que é o homem para que lhe dês atenção? [E] o filho do homem, para que com ele te importes?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 144, 4, 'O homem é semelhante a um sopro; seus dias, como a sombra que passa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 144, 5, 'Ó SENHOR, abaixa teus céus, e desce; toca os montes, e fumeguem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 144, 6, 'Lança relâmpagos, e os dispersa; envia tuas flechas, e os derrota.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 144, 7, 'Estende tuas mãos desde o alto; livra-me, e resgata-me das muitas águas, das mãos dos filhos de estrangeiros;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 144, 8, 'Cuja boca fala coisas inúteis, e sua mão direita é a mão direita da mentira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 144, 9, 'Ó Deus, a ti cantarei uma canção nova; com harpa [e] instrumento de dez cordas tocarei música a ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 144, 10, '[Tu és] o que dás vitória aos reis, [e] livras a Davi, teu servo, da espada maligna.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 144, 11, 'Livra-me e resgata-me das mãos dos filhos de estrangeiros; cuja boca fala mentiras, e sua mão direita é mão direita de falsidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 144, 12, 'Para que nossos filhos [sejam] como plantas, que crescem em sua juventude; [e] nossas filhas [sejam] como esquinas entalhadas ao modo do palácio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 144, 13, 'Nossos celeiros sejam cheios de todos os tipos de mantimentos; nosso gado seja aos milhares, e dezenas de milhares em nossos campos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 144, 14, 'Nossos bois sejam vigorosos; não haja nem assalto, nem fugas, nem gritos em nossas ruas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 144, 15, 'Bem-aventurado é o povo que assim lhe [acontece] ; bem-aventurado é o povo cujo Deus é o SENHOR!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 145, 1, 'Cântico de Davi: Eu te exaltarei, meu Deus [e] Rei; e bendirei teu nome para todo o sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 145, 2, 'Todo dia eu te bendirei, e louvarei teu nome para todo o sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 145, 3, 'O SENHOR é grande e muito louvável; sua grandeza é incompreensível.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 145, 4, 'Geração após geração louvará tuas obras, e anunciarão tuas proezas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 145, 5, 'Eu falarei da honra gloriosa de tua majestade, e de teus feitos maravilhosos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 145, 6, 'E falarão do poder de teus assombrosos feitos; e eu contarei tua grandeza.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 145, 7, 'Declararão a lembrança de tua grande bondade; e anunciarão tua justiça alegremente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 145, 8, 'Piedoso e misericordioso é o SENHOR; ele demora para se irar, e tem grande bondade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 145, 9, 'O SENHOR é bom para com todos; e suas misericórdias [estão] sobre todas as obras que ele fez.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 145, 10, 'Todas as tuas obras louvarão a ti, SENHOR; e teus santos te bendirão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 145, 11, 'Contarão a glória de teu reino, e falarão de teu poder.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 145, 12, 'Para anunciarem aos filhos dos homens suas proezas, e a honra gloriosa de seu reino.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 145, 13, 'Teu reino é um reino eterno, e teu domínio [dura] geração após geração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 145, 14, 'O SENHOR segura todos os que caem, e levanta todos os abatidos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 145, 15, 'Os olhos de todos esperam por ti, e tu lhes dás seu alimento ao seu tempo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 145, 16, 'Tu abres tua mão, e sacias o desejo de todo ser vivo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 145, 17, 'O SENHOR [é] justo em todos os seus caminhos, e bondoso em todas as suas obras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 145, 18, 'O SENHOR está perto de todos os que o chamam; de todos os que clamam a ele sinceramente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 145, 19, 'Ele faz a vontade dos que o temem; e ouve o clamor deles, e os salva.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 145, 20, 'O SENHOR protege a todos os que o amam; porém destrói a todos os perversos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 145, 21, 'Minha boca anunciará louvores ao SENHOR; e todo [ser feito de] carne louvará seu santo nome para todo o sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 146, 1, 'Aleluia! Louva ao SENHOR, ó minha alma!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 146, 2, 'Louvarei ao SENHOR durante [toda] a minha vida; cantarei louvores a meu Deus enquanto eu [existir] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 146, 3, 'Não ponhas tua confiança em príncipes; em filhos de homens, em quem não há salvação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 146, 4, 'O espírito dele [s] sai, e volta para sua terra; naquele mesmo dia seus pensamentos perecem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 146, 5, 'Bem-aventurado aquele que [tem] o Deus de Jacó como sua ajuda, cuja esperança está no SENHOR seu Deus;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 146, 6, 'Que fez os céus e a terra, o mar, e tudo o que neles [há] ; que guarda a fidelidade para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 146, 7, 'Que faz juízo aos oprimidos, que dá pão aos famintos; o SENHOR solta aos presos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 146, 8, 'O SENHOR abre [os olhos] dos cegos; o SENHOR levanta aos abatidos; o SENHOR ama aos justos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 146, 9, 'O SENHOR guarda os estrangeiros; sustenta o órfão e a viúva; mas põe dificuldades ao caminho dos perversos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 146, 10, 'O SENHOR reinará eternamente. Ó Sião, o teu Deus [reinará] geração após geração. Aleluia!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 147, 1, 'Louvai ao SENHOR, porque é bom cantar louvores ao nosso Deus; porque agradável e merecido [é] o louvor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 147, 2, 'O SENHOR edifica a Jerusalém; [e] ajunta os dispersos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 147, 3, 'Ele sara aos de coração partido, e os cura de suas dores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 147, 4, 'Ele conta o número das estrelas; chama todas elas pelos seus nomes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 147, 5, 'O nosso Senhor é grande e muito poderoso; seu entendimento é incomensurável.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 147, 6, 'O SENHOR levanta aos mansos; [e] abate aos perversos até a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 147, 7, 'Cantai ao SENHOR em agradecimento; cantai louvores ao nosso Deus com harpa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 147, 8, 'Ele que cobre o céu com nuvens, que prepara chuva para a terra, que faz os montes produzirem erva;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 147, 9, 'Que dá ao gado seu pasto; e [também] aos filhos dos corvos, quando clamam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 147, 10, 'Ele não se agrada da força do cavalo, nem se contenta com as pernas do homem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 147, 11, 'O SENHOR se agrada dos que o temem, daqueles que esperam por sua bondade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 147, 12, 'Louva, Jerusalém, ao SENHOR; celebra ao teu Deus, ó Sião.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 147, 13, 'Porque ele fortifica os ferrolhos de tuas portas; ele abençoa a teus filhos dentro de ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 147, 14, '[Ele é] o que dá paz às tuas fronteiras; e te farta com o melhor trigo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 147, 15, 'Que envia sua ordem à terra; sua palavra corre velozmente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 147, 16, 'Que dá a neve como a lã; espalha a geada como a cinza.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 147, 17, 'Que lança seu gelo [em] pedaços; quem pode subsistir ao seu frio?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 147, 18, 'Ele manda sua palavra, e os faz derreter; faz soprar seu vento, [e] escorrem-se as águas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 147, 19, 'Ele declara suas palavras a Jacó; e seus estatutos e seus juízos a Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 147, 20, 'Ele não fez assim a nenhuma [outra] nação; [e] não conhecem os juízos [dele] . Louvai ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 148, 1, 'Aleluia! Louvai ao SENHOR desde os céus; louvai-o nas alturas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 148, 2, 'Louvai-o todos os seus anjos; louvai-o todos os seus exércitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 148, 3, 'Louvai-o, sol e lua; louvai-o, todas as estrelas luminosas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 148, 4, 'Louvai-o, céus dos céus, e as águas que [estais] sobre os céus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 148, 5, 'Louvem ao nome do SENHOR; porque pela ordem dele foram criados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 148, 6, 'E os firmou para todo o sempre; e deu [tal] decreto, que não será traspassado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 148, 7, 'Louvai ao SENHOR [vós] da terra: os monstros marinhos, e todos os abismos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 148, 8, 'O fogo e a saraiva, a neve e o vapor; o vento tempestuoso, que executa sua palavra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 148, 9, 'Os montes e todos os morros; árvores frutíferas, e todos os cedros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 148, 10, 'As feras, e todo o gado; répteis, e aves que tem asas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 148, 11, 'Os reis da terra, e todos os povos; os príncipes, e todos os juízes da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 148, 12, 'Os rapazes, e também as moças; os velhos com os jovens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 148, 13, 'Louvem ao nome do SENHOR; pois só o nome dele é exaltado; sua majestade [está] sobre a terra e o céu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 148, 14, 'E ele exaltou o poder de seu povo: o louvor de todos os seus santos, os filhos de Israel, o povo [que está] perto dele. Aleluia!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 149, 1, 'Aleluia! Cantai ao SENHOR um cântico novo; [haja] louvor a ele na congregação dos santos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 149, 2, 'Alegre-se Israel em seu Criador; os filhos de Sião se encham de alegria em seu Rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 149, 3, 'Louvem seu nome com danças; cantai louvores a ele com tamborim e harpa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 149, 4, 'Porque o SENHOR se agrada de seu povo; ele ornará os mansos com salvação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 149, 5, 'Saltem de prazer [seus] santos pela glória; fiquem contentes sobre suas camas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 149, 6, 'Exaltações a Deus [estarão] em suas gargantas; e espada afiada [estará] em sua mão,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 149, 7, 'Para se vingarem das nações, e repreenderem aos povos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 149, 8, 'Para prenderem a seus reis com correntes, e seus nobres com grilhões de ferro;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 149, 9, 'Para executarem sobre eles a sentença escrita; esta [será] a glória de todos os seus santos. Aleluia!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 150, 1, 'Aleluia! Louvai a Deus em seu santuário; louvai-o no firmamento de seu poder.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 150, 2, 'Louvai-o por suas proezas; louvai-o conforme a imensidão de sua grandeza.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 150, 3, 'Louvai-o com com de trombeta; louvai-o com lira e harpa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 150, 4, 'Louvai-o com tamborim e flauta; louvai-o com instrumentos de cordas e de sopro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 150, 5, 'Louvai-o com címbalos bem sonoros; louvai-o com címbalos de sons de alegria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 19, 'Salmos', 'Sl', 150, 6, 'Tudo quanto tem fôlego, louve ao SENHOR! Aleluia!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 1, 1, 'Provérbios de Salomão, filho de Davi, rei de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 1, 2, 'Para conhecer a sabedoria e a instrução; para entender as palavras da prudência;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 1, 3, 'Para obter a instrução do entendimento; justiça, juízo e equidades;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 1, 4, 'Para dar inteligência aos simples, conhecimento e bom senso aos jovens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 1, 5, 'O sábio ouvirá, e crescerá em conhecimento; o bom entendedor obterá sábios conselhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 1, 6, 'Para entender provérbios e [sua] interpretação; as palavras dos sábios, e seus enigmas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 1, 7, 'O temor ao SENHOR [é] o principio do conhecimento; os tolos desprezam a sabedoria e a instrução.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 1, 8, 'Filho meu, ouve a instrução de teu pai; e não abandones a doutrina de tua mãe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 1, 9, 'Porque [serão] um ornamento gracioso para tua cabeça; e colares para teu pescoço.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 1, 10, 'Filho meu, se os pecadores tentarem te convencer, não te deixes influenciar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 1, 11, 'Se disserem: Vem conosco, vamos espiar [derramamento] de sangue; preparemos uma emboscada ao inocente sem razão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 1, 12, 'Vamos tragá-los vivos, como o Xeol; e inteiros, como os que descem à cova.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 1, 13, 'Acharemos toda espécie de coisas valiosas, encheremos nossas casas de despojos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 1, 14, 'Lança tua sorte entre nós, compartilharemos todos de uma [só] bolsa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 1, 15, 'Filho meu, não sigas teu caminho com eles; desvia teu pé [para longe] de onde eles passarem;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 1, 16, 'Porque os pés deles correm para o mal, e se apressam para derramar sangue.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 1, 17, 'Certamente [é] inútil se estender a rede diante da vista de todas as aves;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 1, 18, 'Porém estes estão esperando [o derramamento] de seu [próprio] sangue; e preparam emboscada para suas [próprias] almas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 1, 19, 'Assim [são] os caminhos de todo aquele que tem ganância pelo lucro desonesto; ela tomará a alma daqueles que a tem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 1, 20, 'A sabedoria grita pelas ruas; nas praças ela levanta sua voz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 1, 21, 'Ela clama nas encruzilhadas, onde [passam] muita gente; às entradas das portas, nas cidades ela diz suas mensagens:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 1, 22, 'Até quando, ó tolos, amareis a tolice? E vós zombadores, desejareis a zombaria? E [vós] loucos, odiareis o conhecimento?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 1, 23, 'Convertei-vos à minha repreensão; eis que vos derramarei meu espírito, [e] vos farei saber minhas palavras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 1, 24, '[Mas] porque eu clamei, e recusastes; estendi minha mão, e não houve quem desse atenção,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 1, 25, 'E rejeitastes todo o meu conselho, e não quisestes minha repreensão,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 1, 26, 'Também eu rirei em vosso sofrimento, [e] zombarei, quando vier vosso medo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 1, 27, 'Quando vier vosso temor como tempestade, e a causa de vosso sofrimento como ventania, quando vier sobre vós a opressão e a angústia,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 1, 28, 'Então clamarão a mim; porém eu não responderei; de madrugada me buscarão, porém não me acharão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 1, 29, 'Porque odiaram o conhecimento; e escolheram não temer ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 1, 30, 'Não concordaram com meu conselho, [e] desprezaram toda a minha repreensão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 1, 31, 'Por isso comerão do fruto do seu [próprio] caminho, e se fartarão de seus [próprios] conselhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 1, 32, 'Pois o desvio dos tolos os matará, e a confiança dos loucos os destruirá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 1, 33, 'Porém aquele que me ouvir habitará em segurança, e estará tranquilo do temor do mal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 2, 1, 'Filho meu, se aceitares minhas palavras, e depositares em ti meus mandamentos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 2, 2, 'Para fazeres teus ouvidos darem atenção à sabedoria, [e] inclinares teu coração à inteligência;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 2, 3, 'E se clamares à prudência, [e] à inteligência dirigires tua voz;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 2, 4, 'Se tu a buscares como a prata, e a procurares como que a tesouros escondidos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 2, 5, 'Então entenderás o temor ao SENHOR, e acharás o conhecimento de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 2, 6, 'Porque o SENHOR dá sabedoria; de sua boca [vem] o conhecimento e o entendimento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 2, 7, 'Ele reserva a boa sabedoria para os corretos; [ele é] escudo para os que andam em sinceridade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 2, 8, 'Para guardar os caminhos do juízo; e conservar os passos de seus santos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 2, 9, 'Então entenderás a justiça e o juízo, e a equidade; [e] todo bom caminho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 2, 10, 'Quando a sabedoria entrar em teu coração, e o conhecimento for agradável à tua alma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 2, 11, 'O bom senso te guardará, e o entendimento te preservará:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 2, 12, '- Para te livrar do mau caminho, e dos homens que falam perversidades;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 2, 13, 'Que deixam as veredas da justiça para andarem pelos caminhos das trevas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 2, 14, 'Que se alegram em fazer o mal, e se enchem de alegria com as perversidades dos maus;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 2, 15, 'Cujas veredas são distorcidas, e desviadas em seus percursos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 2, 16, '- Para te livrar da mulher estranha, e da pervertida, [que] lisonjeia com suas palavras;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 2, 17, 'Que abandona o guia de sua juventude, e se esquece do pacto de seu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 2, 18, 'Porque sua casa se inclina para a morte, e seus caminhos para os mortos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 2, 19, 'Todos os que entrarem a ela, não voltarão mais; e não alcançarão os caminhos da vida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 2, 20, '- Para andares no caminho dos bons, e te guardares nas veredas dos justos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 2, 21, 'Porque os corretos habitarão a terra; e os íntegros nela permanecerão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 2, 22, 'Porém os perversos serão cortados da terra, e os infiéis serão arrancados dela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 3, 1, 'Filho meu, não te esqueças de minha lei; e que teu coração guarde meus mandamentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 3, 2, 'Porque te acrescentarão extensão de dias, e anos de vida e paz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 3, 3, 'Que a bondade e a fidelidade não te desamparem; amarra-as junto ao teu pescoço; escreve-as na tábua de teu coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 3, 4, 'Então tu acharás graça e bom entendimento, aos olhos de Deus e dos homens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 3, 5, 'Confia no SENHOR com todo o teu coração; e não te apoies em teu [próprio] entendimento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 3, 6, 'Dá reconhecimento a ele em todas os teus caminhos; e ele endireitará tuas veredas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 3, 7, 'Não sejas sábio aos teus [próprios] olhos; teme ao SENHOR, e afasta-te do mal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 3, 8, 'Isto será remédio para teu corpo, e alívio para teus ossos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 3, 9, 'Honra ao SENHOR com teus bens, e com a primeira parte de toda a tua renda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 3, 10, 'E teus celeiros se encherão de fartura, e tuas prensas de uvas transbordarão de vinho novo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 3, 11, 'Filho meu, não rejeites a correção do SENHOR, nem te desagrades de sua repreensão;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 3, 12, 'Porque o SENHOR repreende a quem ele ama, assim como o pai ao filho, [a quem] ele quer bem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 3, 13, 'Bem-aventurado o homem que encontra sabedoria, e o homem que ganha conhecimento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 3, 14, 'Porque seu produto é melhor que o produto da prata; e seu valor, mais do que o do ouro fino.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 3, 15, 'Ela é mais preciosa do que rubis; e tudo o que podes desejar não se pode comparar a ela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 3, 16, 'Extensão de dias [há] em sua mão direita; em sua esquerda riquezas e honra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 3, 17, 'Seus caminhos são caminhos agradáveis; e todas as suas veredas são paz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 3, 18, 'Ela é uma árvore de vida para os que dela pegam; e bem-aventurados são todos os que a retêm.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 3, 19, 'O SENHOR com sabedoria fundou a terra; ele preparou os céus com a inteligência.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 3, 20, 'Com seu conhecimento se fenderam os abismos, e as nuvens gotejam orvalho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 3, 21, 'Filho meu, que [estes] não se afastem de teus olhos; guarda a sabedoria e o bom-senso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 3, 22, 'Porque serão vida para tua alma, e graça para teu pescoço.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 3, 23, 'Então andarás por teu caminho em segurança; e com teus pés não tropeçarás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 3, 24, 'Quando te deitares, não terás medo; tu deitarás, e teu sono será suave.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 3, 25, 'Não temas o pavor repentino; nem da assolação dos perversos, quando vier.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 3, 26, 'Porque o SENHOR será tua esperança; e ele guardará teus pés para que não sejam presos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 3, 27, 'Não detenhas o bem daqueles que possuem o direito, se tiveres em tuas mãos poder para o fazeres.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 3, 28, 'Não digas a teu próximo: Vai, e volta [depois] , que amanhã te darei; se tu tiveres contigo [o que ele te pede] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 3, 29, 'Não planejes o mal contra teu próximo, pois ele mora tendo confiança em ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 3, 30, 'Não brigues contra alguém sem motivo, se ele não fez mal contra ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 3, 31, 'Não tenhas inveja do homem violento, nem escolhas [seguir] algum dos caminhos dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 3, 32, 'Porque o SENHOR abomina os perversos; mas ele [guarda] o seu segredo com os justos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 3, 33, 'A maldição do SENHOR [está] na casa do perverso; porém ele abençoa a morada dos justos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 3, 34, 'Certamente ele zombará dos zombadores; mas dará graça aos humildes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 3, 35, 'Os sábios herdarão honra; porém os loucos terão sobre si confusão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 4, 1, 'Ouvi, filhos, a correção do pai; e prestai atenção, para que conheçais o entendimento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 4, 2, 'Pois eu vos dou boa doutrina; não deixeis a minha lei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 4, 3, 'Porque eu era filho do meu pai; tenro, e único perante a face de minha mãe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 4, 4, 'E ele me ensinava, e me dizia: Que teu coração retenha minhas palavras; guarda meus mandamentos, e vive.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 4, 5, 'Adquire sabedoria, adquire entendimento; [e] não te esqueças nem te desvies das palavras de minha boca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 4, 6, 'Não a abandones, e ela te guardará; ama-a, e ela te conservará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 4, 7, 'O principal é a sabedoria; adquire sabedoria, e acima de tudo o que adquirires, adquire entendimento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 4, 8, 'Exalta-a, e ela te exaltará; quando tu a abraçares, ela te honrará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 4, 9, 'Ela dará a tua cabeça um ornamento gracioso; ela te entregará uma bela coroa.')
